function validate([nums, x]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each value in nums is between 1 and 10^9.';
  if (!Number.isInteger(x) || x < 0 || x >= nums.length) return 'x must be at least 0 and smaller than the length of nums.';
  return null;
}

