function minAbsoluteDifference(nums, x) {
  const sorted = [];
  let best = Infinity;

  function lowerBound(target) {
    let left = 0;
    let right = sorted.length;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (sorted[mid] < target) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    return left;
  }

  for (let j = x; j < nums.length; j++) {
    const earlier = nums[j - x];
    sorted.splice(lowerBound(earlier), 0, earlier);
    const pos = lowerBound(nums[j]);
    if (pos < sorted.length) {
      best = Math.min(best, sorted[pos] - nums[j]);
    }
    if (pos > 0) {
      best = Math.min(best, nums[j] - sorted[pos - 1]);
    }
  }
  return best;
}

