function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  const mode = Math.floor(rand() * 3);
  const top = mode === 0 ? 1e9 : mode === 1 ? (size === 'large' ? 1e6 : 30) : (size === 'large' ? 5000 : 6);
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const r = rand();
  const x = r < 0.15 ? 0 : r < 0.3 ? n - 1 : Math.floor(rand() * rand() * n);
  return [nums, Math.min(x, n - 1)];
}
